(function(){
  // Minimal stub for QRCode.toCanvas to avoid external CDN and ORB blocks
  // This does NOT generate a real QR code; it renders a placeholder.
  function drawPlaceholder(canvas, text){
    if (!canvas) return;
    var ctx = canvas.getContext('2d');
    var w = canvas.width || 200;
    var h = canvas.height || 200;
    canvas.width = w;
    canvas.height = h;
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0,0,w,h);
    ctx.fillStyle = '#000000';
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 2;
    // simple border
    ctx.strokeRect(4,4,w-8,h-8);
    // placeholder pattern
    for(var i=0;i<10;i++){
      ctx.fillRect(10 + i*16, 10, 8, 8);
      ctx.fillRect(10, 10 + i*16, 8, 8);
    }
    // text label
    ctx.font = '12px Segoe UI, Arial';
    ctx.textAlign = 'center';
    ctx.fillText('QRCode', w/2, h/2 - 6);
    ctx.fillText((text||'ID'), w/2, h/2 + 12);
  }
  window.QRCode = {
    toCanvas: function(canvas, text, options){
      return new Promise(function(resolve){
        try{
          drawPlaceholder(canvas, text);
        }catch(e){ /* ignore */ }
        resolve();
      });
    }
  };
})();